import json
from pathlib import Path


def load_payload(path):
    path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise ValueError("cannot read payload file: %s" % path) from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid JSON payload: %s" % path) from exc
    if isinstance(data, (dict, list)):
        return data
    raise ValueError("top-level value must be an object or array: %s" % path)

