"""builds — failure_evidence：修订证据失败率。"""
import math

_CATEGORIES = ("prepare", "copy", "verify")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _normalize(raw):
    if not isinstance(raw, dict):
        raise ValueError("record must be an object")
    idv = raw.get("id")
    if not isinstance(idv, str) or not idv.strip():
        raise ValueError("id must be a non-empty string")
    idv = idv.strip()

    revision = raw.get("revision")
    if not _is_int(revision) or revision < 0:
        raise ValueError("revision must be an int >= 0")

    owner = raw.get("owner")
    if not isinstance(owner, str) or not owner.strip():
        raise ValueError("owner must be a non-empty string")
    owner = owner.strip().lower()

    category = raw.get("category")
    if not isinstance(category, str) or not category.strip():
        raise ValueError("category must be a non-empty string")
    category = category.strip().lower()
    if category not in _CATEGORIES:
        raise ValueError("category must be prepare/copy/verify")

    tags = raw.get("tags")
    if not isinstance(tags, list):
        raise ValueError("tags must be a list")
    norm_tags = []
    for tag in tags:
        if not isinstance(tag, str) or not tag.strip():
            raise ValueError("tags must be a list of non-empty strings")
        norm_tags.append(tag.strip().lower())
    norm_tags = sorted(set(norm_tags))

    failures = raw.get("failures")
    if not _is_int(failures) or failures < 0:
        raise ValueError("failures must be an int >= 0")

    total = raw.get("total")
    if not _is_int(total) or total < 1:
        raise ValueError("total must be an int >= 1")

    lag = raw.get("lag")
    if not _is_int(lag) or lag < 0:
        raise ValueError("lag must be an int >= 0")

    valid = raw.get("valid")
    if not isinstance(valid, bool):
        raise ValueError("valid must be a bool")

    if failures > total:
        raise ValueError("failures must be <= total")

    return {
        "id": idv,
        "revision": revision,
        "owner": owner,
        "category": category,
        "tags": norm_tags,
        "failures": failures,
        "total": total,
        "lag": lag,
        "valid": valid,
    }


def _score(record, offset):
    value = math.ceil(20 * record["failures"] / record["total"]) + offset
    return max(0, min(20, value))


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payloads must match contract inputs")
    payload = payloads[0]
    if not isinstance(payload, list):
        raise ValueError("builds input must be a record array")

    offset = contract.get("offset")
    if not _is_int(offset):
        raise ValueError("offset must be an int")

    normalized = [_normalize(record) for record in payload]

    seen = {}
    for record in normalized:
        key = (record["id"], record["revision"])
        canon = (
            record["id"], record["revision"], record["owner"], record["category"],
            tuple(record["tags"]), record["failures"], record["total"],
            record["lag"], record["valid"],
        )
        if key in seen:
            if seen[key] != canon:
                raise ValueError("conflicting revisions for same id")
        else:
            seen[key] = canon

    latest = {}
    for record in normalized:
        idv = record["id"]
        if idv not in latest or record["revision"] > latest[idv]["revision"]:
            latest[idv] = record

    records = []
    for idv in sorted(latest):
        record = latest[idv]
        records.append({
            "id": idv,
            "source": contract["name"],
            "owner": record["owner"],
            "tags": record["tags"],
            "category": record["category"],
            "score": _score(record, offset),
        })
    records.sort(key=lambda r: (r["source"], r["id"]))

    return {
        "name": contract["name"],
        "result": {
            "records": records,
            "count": len(records),
            "score_total": sum(r["score"] for r in records),
        },
    }

