"""release_risk — risk_ranking：风险排名。"""


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    raise ValueError("input must be a component wrapper with name/result")


def _merge(payloads):
    merged = {}
    for payload in payloads:
        result = _unwrap(payload)
        if not isinstance(result, dict):
            raise ValueError("wrapper result must be an object")
        records = result.get("records")
        if not isinstance(records, list):
            raise ValueError("wrapper result must contain a records list")
        for record in records:
            if not isinstance(record, dict):
                raise ValueError("record must be an object")
            source = record.get("source")
            idv = record.get("id")
            if not isinstance(source, str) or not isinstance(idv, str):
                raise ValueError("record must have source and id")
            if not _is_int(record.get("score")):
                raise ValueError("record score must be an int")
            key = (source, idv)
            if key in merged and merged[key] != record:
                raise ValueError("source/id conflict")
            merged[key] = record
    return list(merged.values())


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payloads must match contract inputs")

    threshold = contract.get("threshold")
    if not _is_int(threshold):
        raise ValueError("threshold must be an int")
    limit = contract.get("limit")
    if not _is_int(limit) or limit < 0:
        raise ValueError("limit must be an int >= 0")

    records = _merge(payloads)
    selected = [r for r in records if r["score"] >= threshold]
    ranked = sorted(selected, key=lambda r: (-r["score"], r["source"], r["id"]))
    top = ranked[:limit]

    records_out = sorted(top, key=lambda r: (r["source"], r["id"]))
    ranking = ["%s:%s" % (r["source"], r["id"]) for r in ranked]
    score_total = sum(r["score"] for r in top)

    return {
        "name": contract["name"],
        "result": {
            "records": records_out,
            "ranking": ranking,
            "score_total": score_total,
        },
    }

