def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payloads must match contract inputs")

    reviewers = contract.get("reviewers")
    if not isinstance(reviewers, list) or not all(isinstance(r, str) and r for r in reviewers):
        raise ValueError("reviewers must be a list of non-empty strings")

    records = _merge(payloads)
    loads = {reviewer: 0 for reviewer in reviewers}
    assignments = []

    for record in sorted(records, key=lambda r: (-r["score"], r["source"], r["id"])):
        chosen = min(loads, key=lambda name: (loads[name], name))
        loads[chosen] += record["score"]
        assignments.append({
            "id": "%s:%s" % (record["source"], record["id"]),
            "reviewer": chosen,
        })

    records_out = sorted(records, key=lambda r: (r["source"], r["id"]))
    assignments.sort(key=lambda a: a["id"])

    return {
        "name": contract["name"],
        "result": {
            "records": records_out,
            "assignments": assignments,
            "loads": loads,
        },
    }

"""remediation_waves — remediation_plan：依赖波次与条件修复。"""
_CATEGORY_ORDER = {"prepare": 0, "copy": 1, "verify": 2}


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    raise ValueError("input must be a component wrapper with name/result")


def _merge(payloads):
    merged = {}
    for payload in payloads:
        result = _unwrap(payload)
        if not isinstance(result, dict):
            raise ValueError("wrapper result must be an object")
        records = result.get("records")
        if not isinstance(records, list):
            raise ValueError("wrapper result must contain a records list")
        for record in records:
            if not isinstance(record, dict):
                raise ValueError("record must be an object")
            source = record.get("source")
            idv = record.get("id")
            if not isinstance(source, str) or not isinstance(idv, str):
                raise ValueError("record must have source and id")
            if not _is_int(record.get("score")):
                raise ValueError("record score must be an int")
            key = (source, idv)
            if key in merged and merged[key] != record:
                raise ValueError("source/id conflict")
            merged[key] = record
    return list(merged.values())


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payloads must match contract inputs")

    threshold = contract.get("threshold")
    if not _is_int(threshold):
        raise ValueError("threshold must be an int")
    only_if_blocking = contract.get("only_if_blocking")
    if not isinstance(only_if_blocking, bool):
        raise ValueError("only_if_blocking must be a bool")

    records = _merge(payloads)

    for record in records:
        category = record.get("category")
        if not isinstance(category, str) or category not in _CATEGORY_ORDER:
            raise ValueError("record category must be prepare/copy/verify")
        tags = record.get("tags")
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ValueError("record tags must be a list of strings")

    if only_if_blocking:
        blocking = any(
            "blocking" in record["tags"] and record["score"] >= threshold
            for record in records
        )
        kept = records if blocking else []
    else:
        kept = records

    nodes = []
    for record in kept:
        nodes.append({
            "full_id": "%s:%s" % (record["source"], record["id"]),
            "duration": 1 + record["score"] // 5,
            "category": record["category"],
        })

    for node in nodes:
        node["deps"] = [
            other for other in nodes
            if _CATEGORY_ORDER[other["category"]] < _CATEGORY_ORDER[node["category"]]
        ]

    finish = {}
    path = {}
    committed = set()
    waves = []
    pending = {node["full_id"] for node in nodes}

    while pending:
        ready = [
            node for node in nodes
            if node["full_id"] in pending
            and all(dep["full_id"] in committed for dep in node["deps"])
        ]
        if not ready:
            raise ValueError("cyclic dependency")
        ready.sort(key=lambda node: node["full_id"])
        wave = []
        for node in ready:
            deps = node["deps"]
            if not deps:
                finish_value = node["duration"]
                complete_path = [node["full_id"]]
            else:
                max_finish = max(finish[dep["full_id"]] for dep in deps)
                best = min(
                    (dep for dep in deps if finish[dep["full_id"]] == max_finish),
                    key=lambda dep: path[dep["full_id"]],
                )
                finish_value = node["duration"] + max_finish
                complete_path = path[best["full_id"]] + [node["full_id"]]
            finish[node["full_id"]] = finish_value
            path[node["full_id"]] = complete_path
            wave.append(node["full_id"])
        waves.append(wave)
        committed.update(node["full_id"] for node in ready)
        pending.difference_update(node["full_id"] for node in ready)

    if nodes:
        makespan = max(finish.values())
        endpoint = min(
            nodes,
            key=lambda node: (-finish[node["full_id"]], path[node["full_id"]]),
        )
        critical_path = path[endpoint["full_id"]]
    else:
        makespan = 0
        critical_path = []

    earliest_finish = {node["full_id"]: finish[node["full_id"]] for node in nodes}
    records_out = sorted(kept, key=lambda r: (r["source"], r["id"]))

    return {
        "name": contract["name"],
        "result": {
            "records": records_out,
