        if "outputs" not in p.relative_to(ROOT).parts
    )


def main():
    contract_paths = _contracts()
    contracts = {}
    for path in contract_paths:
        contracts[str(path)] = json.loads(path.read_text(encoding="utf-8"))

    output_to_path = {}
    for path, contract in contracts.items():
        output_to_path[contract["output"]] = path

    deps = {path: [] for path in contracts}
    for path, contract in contracts.items():
        for inp in contract["inputs"]:
            if inp in output_to_path:
                deps[path].append(output_to_path[inp])

    children = {path: [] for path in contracts}
    indegree = {}
    for path, ds in deps.items():
